import{_ as a,o as t,c as o,ae as n}from"./chunks/framework.EHGTsUvI.js";const u=JSON.parse('{"title":"Information Unavailable","description":"","frontmatter":{"title":"Information Unavailable"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md"}'),i={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Factories/shirt.md"};function r(l,e,s,p,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="information-unavailable" tabindex="-1">Information Unavailable <a class="header-anchor" href="#information-unavailable" aria-label="Permalink to &quot;Information Unavailable&quot;">​</a></h1><p>This page does not currently contain any confirmed information.</p><p>The <strong>Farming And Friends Wiki team</strong> is currently working to research and verify the information for this page so that we can provide accurate and reliable information to the community.</p><h2 id="can-you-help" tabindex="-1">Can You Help? <a class="header-anchor" href="#can-you-help" aria-label="Permalink to &quot;Can You Help?&quot;">​</a></h2><p>If you have accurate information about this topic, we&#39;d love to hear from you!</p><p>If you believe you can provide information, screenshots, or other useful details, please <strong>contact the Wiki team</strong> and let us know what you have.</p><blockquote><p><strong>Note:</strong> Please only provide information that you believe is accurate. Where possible, screenshots or in-game confirmation are greatly appreciated.</p></blockquote><p>Thank you for helping us improve the <strong>Farming And Friends Wiki</strong>!</p><h1 id="shirt-factory" tabindex="-1">SHIRT FACTORY <a class="header-anchor" href="#shirt-factory" aria-label="Permalink to &quot;SHIRT FACTORY&quot;">​</a></h1><p>Shirt Boxes are an animal derived product produced from Sheep using Wool Bundles. Sheep are placed inside fence, given food, and adequate space to grow Wool on their body. Wool is sheared by standing close to the sheep and clicking on shear. Shears as an equipment is NOT required.</p><blockquote><p>Shirts are the the final product that can be made from sheeps. It can be sold or fulfilled in company related tasks.</p></blockquote><p>| Information|Details | | Purchase Price|70,000 coins| |Sell Price|14,000 coins| |Main Inputs|Wool Bundles| |Product|Shirt Box| |Output|Pallet of Shirt Box | |Selling Location|Animal Co|</p><p>##Factory Information</p><h3 id="required-materials" tabindex="-1">Required Materials <a class="header-anchor" href="#required-materials" aria-label="Permalink to &quot;Required Materials&quot;">​</a></h3><p>|Material | Amount| |Wool Bundle |1| |Shirt Box Produced|2|</p><blockquote><p>The Shirt Factory uses Wool Bundles as the only input</p></blockquote><p>This means a full pallet of 27 Shirts require 13.5 Wool Bundles</p><h2 id="production-time" tabindex="-1">Production Time <a class="header-anchor" href="#production-time" aria-label="Permalink to &quot;Production Time&quot;">​</a></h2><p>The Shirt Factory does not currently have a reliably documented fixed production time in the available community documentations.</p><p>Production is handled through the factory&#39;s internal production process rather than simple crop-style growth timer.</p><blockquote><p>Note: Production time may vary depending on the current version of the game. This section should be updated if an exact in-game product time is confirmed.</p></blockquote><h2 id="products-produced" tabindex="-1">Products Produced <a class="header-anchor" href="#products-produced" aria-label="Permalink to &quot;Products Produced&quot;">​</a></h2><p>|Product|Amount| |Shirt Box|27 Boxes|</p><blockquote><p>The Shirt Factory Produces Shirt Boxes.</p></blockquote><p>A full pallet contains:</p><p>Shirts are produced in batches of 2 boxes from 1 wool bundle.</p><h2 id="selling-price" tabindex="-1">Selling Price <a class="header-anchor" href="#selling-price" aria-label="Permalink to &quot;Selling Price&quot;">​</a></h2><p>Shirts can be sold at AnimalCo.</p><p>The current community documentation lists the maximum price at approximately 9375 coins per shirt box.</p><p>A full pallet of 27 shirt boxes could therefore sell for approximately:</p><p>27 x 9375 = 253,125</p><blockquote><p>Note: Selling prices can change with game updates, so verify the current in-game price before treating this as a permanent value.</p></blockquote><h2 id="required-equipment" tabindex="-1">Required Equipment <a class="header-anchor" href="#required-equipment" aria-label="Permalink to &quot;Required Equipment&quot;">​</a></h2><p>To operate and transport Shirts efficiently, you will need:</p><ul><li>Sheep for producing wool</li><li>Spindle Machine for producing wool bundles</li><li>Transport Equipment</li><li>Flatbed Hauler S-500 or any other pallet-capable vehicle</li><li>Forklift for handling Shirt pallets</li></ul><p>A suitable pallet-capable vehicle and forklift are required to efficiently transport Shirt Pallets.</p><h2 id="how-to-use-the-shirt-factory" tabindex="-1">How to Use the Shirt Factory <a class="header-anchor" href="#how-to-use-the-shirt-factory" aria-label="Permalink to &quot;How to Use the Shirt Factory&quot;">​</a></h2><h3 id="_1-purchase-the-shirt-factory" tabindex="-1">1. Purchase the Shirt Factory <a class="header-anchor" href="#_1-purchase-the-shirt-factory" aria-label="Permalink to &quot;1. Purchase the Shirt Factory&quot;">​</a></h3><p>Purchase the Cheese Factory for 70,000 coins and place it on your farm.</p><h3 id="_2-produce-wool" tabindex="-1">2. Produce Wool <a class="header-anchor" href="#_2-produce-wool" aria-label="Permalink to &quot;2. Produce Wool&quot;">​</a></h3><p>You will need Sheep to steady supply of sheer wool.</p><p>Sheep can be sheared by standing near to a sheep with wool 100%, once sheered gives 1 wool per sheep Note: without any sheep efficiency</p><h3 id="_3-place-spindle-machine" tabindex="-1">3. Place Spindle Machine <a class="header-anchor" href="#_3-place-spindle-machine" aria-label="Permalink to &quot;3. Place Spindle Machine&quot;">​</a></h3><p>Place the Spindle Machine for 5000 coins Load the Spindle Machine with 6 sheer wool at one time 3 sheer wool yields 1 wool bundle.</p><h3 id="_4-load-the-shirt-factory" tabindex="-1">4. Load the Shirt Factory <a class="header-anchor" href="#_4-load-the-shirt-factory" aria-label="Permalink to &quot;4. Load the Shirt Factory&quot;">​</a></h3><p>Load the wool bundles from spindle machine onto the input of shirt factory 1 wool bundles -&gt; 2 shirt boxes</p><h3 id="_5-collect-the-shirt-box-pallet" tabindex="-1">5. Collect the Shirt Box Pallet <a class="header-anchor" href="#_5-collect-the-shirt-box-pallet" aria-label="Permalink to &quot;5. Collect the Shirt Box Pallet&quot;">​</a></h3><p>Produced shirts are stored as boxes and eventually forms pallets. A complete pallet contains 27 shirt boxes.</p><h3 id="_6-transport-the-pallet" tabindex="-1">6. Transport the Pallet <a class="header-anchor" href="#_6-transport-the-pallet" aria-label="Permalink to &quot;6. Transport the Pallet&quot;">​</a></h3><p>Once a pallet is ready, use a suitable pallet-capable vehicle such as the Flatbed Hauler S-500, and a Forklift to move it.</p><h3 id="_7-sell-the-shirt-box" tabindex="-1">7. Sell the Shirt Box <a class="header-anchor" href="#_7-sell-the-shirt-box" aria-label="Permalink to &quot;7. Sell the Shirt Box&quot;">​</a></h3><p>Take the finished Shirt box to Animal Co to sell it.</p><p>Shirt Production Chain</p><p>Sheep -&gt; Sheer Wool -&gt; Wool Bundles -&gt; Shirt Factory -&gt; Shirt Box -&gt; Animal Co.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      Sheep</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    Sheer Wool</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  Put into spindle</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>    Wool Bundles</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Factory       Sell</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>Production   Sell Point</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>Transport</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>Sell</span></span></code></pre></div>`,55)])])}const m=a(i,[["render",r]]);export{u as __pageData,m as default};
